<?php session_start();require 'admin_db.php';$uid=$_SESSION['userID']??$_SESSION['SID']??'';if(!$uid)die('Please login as student.');$q=trim($_GET['q']??'');$like="%$q%";$s=mysqli_prepare($conn,"SELECT g.*,COUNT(DISTINCT CASE WHEN j.leaveDate IS NULL OR j.leaveDate='0000-00-00' THEN j.student_UID END) members FROM group_info g LEFT JOIN student_joins_group j ON j.groupID=g.groupID WHERE g.targeted_subjects LIKE ? GROUP BY g.groupID HAVING members<5 ORDER BY g.groupID");mysqli_stmt_bind_param($s,'s',$like);mysqli_stmt_execute($s);$groups=mysqli_stmt_get_result($s);$my=mysqli_query($conn,"SELECT g.*,COUNT(j.student_UID) members FROM group_info g JOIN student_joins_group j ON j.groupID=g.groupID WHERE j.student_UID='".mysqli_real_escape_string($conn,$uid)."' AND (j.leaveDate IS NULL OR j.leaveDate='0000-00-00') GROUP BY g.groupID");if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['join'])){$gid=$_POST['groupID'];$s=mysqli_prepare($conn,'SELECT COUNT(*) n FROM student_joins_group WHERE groupID=? AND (leaveDate IS NULL OR leaveDate="0000-00-00")');mysqli_stmt_bind_param($s,'s',$gid);mysqli_stmt_execute($s);$n=mysqli_fetch_assoc(mysqli_stmt_get_result($s))['n'];if($n<5){$s=mysqli_prepare($conn,'INSERT INTO group_join_requests(groupID,student_UID) VALUES(?,?)');mysqli_stmt_bind_param($s,'ss',$gid,$uid);mysqli_stmt_execute($s);header('Location: mygroup.php');exit;}}?><!doctype html><html><head><title>My Groups</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>My Groups</h1><a class="btn" href="student_dashboard.php">Dashboard</a></div><div class="panel"><h2>My Joined Groups</h2><table><tr><th>Group</th><th>Subject</th><th>Members</th><th>Open</th></tr><?php while($g=mysqli_fetch_assoc($my)):?><tr><td><?=$g['groupID']?></td><td><?=htmlspecialchars($g['targeted_subjects'])?></td><td><?=$g['members']?>/5</td><td><a class="btn" href="group_view.php?groupID=<?=$g['groupID']?>">Open</a></td></tr><?php endwhile;?></table></div><div class="panel"><h2>Find a Group</h2><form><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search interested subject/topic"><button>Search</button></form><table><tr><th>Group</th><th>Subject</th><th>Members</th><th>Join</th></tr><?php while($g=mysqli_fetch_assoc($groups)):?><tr><td><?=$g['groupID']?></td><td><?=htmlspecialchars($g['targeted_subjects'])?></td><td><?=$g['members']?>/5</td><td><form method="post"><input type="hidden" name="groupID" value="<?=$g['groupID']?>"><button name="join">Want to Join</button></form></td></tr><?php endwhile;?></table></div><div class="panel"><a class="btn" href="create_group.php">＋ Form Group</a></div></div></body></html>
